create table xxcus.xxfnd_notification_templates_tl (
    template_code         varchar2(50 byte) not null enable,
    language_code         varchar2(10 byte) not null enable,
    subject               varchar2(500 byte) not null enable,
    body_html             clob not null enable,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxfnd_notification_templates_tl
    add constraint xxfnd_notif_templates_tl_pk primary key ( template_code,
                                                             language_code )
        using index enable;


